// Load submitted students from localStorage or initialize empty
function loadSubmittedStudents() {
    try {
        const stored = localStorage.getItem('submittedStudents');
        if (stored) {
            const parsed = JSON.parse(stored);
            // Convert arrays back to Sets
            const result = {};
            for (const date in parsed) {
                result[date] = new Set(parsed[date]);
            }
            return result;
        }
    } catch (e) {
        console.error('Error loading submitted students from localStorage:', e);
    }
    return {};
}

function saveSubmittedStudents(submittedStudents) {
    try {
        // Convert Sets to arrays for JSON serialization
        const toSave = {};
        for (const date in submittedStudents) {
            toSave[date] = Array.from(submittedStudents[date]);
        }
        localStorage.setItem('submittedStudents', JSON.stringify(toSave));
    } catch (e) {
        console.error('Error saving submitted students to localStorage:', e);
    }
}

let submittedStudents = loadSubmittedStudents(); // Track submitted students by date: submittedStudents[date] = Set of student IDs
let pointCardNightlySubmitTimer = null;
let pointCardNightlySubmitInterval = null;
let pointCardAutoSubmitInFlight = false;
let pointCardNightlySubmitSchedulerStarted = false;

function isPastPointCardSubmitTime(dateStr) {
    if (!dateStr || typeof dateStr !== 'string') {
        return false;
    }
    const parts = dateStr.split('-').map(Number);
    if (parts.length !== 3 || parts.some(n => !Number.isFinite(n))) {
        return false;
    }
    const submitAt = new Date(parts[0], parts[1] - 1, parts[2], 23, 15, 0, 0);
    return Date.now() >= submitAt.getTime();
}

function markStudentSubmitted(dateStr, studentId) {
    if (!dateStr || !studentId) {
        return;
    }
    const id = parseInt(studentId, 10);
    if (!Number.isFinite(id)) {
        return;
    }
    if (!submittedStudents[dateStr]) {
        submittedStudents[dateStr] = new Set();
    }
    submittedStudents[dateStr].add(id);
    saveSubmittedStudents(submittedStudents);
}

function isStudentSubmittedForDate(dateStr, studentId) {
    const id = parseInt(studentId, 10);
    return !!(dateStr && submittedStudents[dateStr] && submittedStudents[dateStr].has(id));
}

function periodHasEnteredStarPoints(periodOrCell) {
    if (!periodOrCell) return false;
    const values = [
        periodOrCell.s,
        periodOrCell.t,
        periodOrCell.a,
        periodOrCell.r,
        periodOrCell.safety_points,
        periodOrCell.teamwork_points,
        periodOrCell.accountability_points,
        periodOrCell.relationships_points
    ];
    return values.some((value) => value !== null && value !== undefined && value !== '');
}

function defaultPointCardPeriod(standardPeriod) {
    return {
        time_range: standardPeriod.time,
        location: standardPeriod.location,
        safety_points: null,
        teamwork_points: null,
        accountability_points: null,
        relationships_points: null,
        points_possible: 0,
        reset: false,
        frenzy: false,
        notes: '',
        reminders: '',
        info: '',
        infractions: []
    };
}

function expandPointCardPeriods(periods) {
    const list = Array.isArray(periods) ? periods : [];
    const standardTimes = new Set(STANDARD_PERIODS.map((sp) => sp.time));
    const byTime = new Map();
    const extras = [];
    list.forEach((period) => {
        if (!period) return;
        const time = String(period.time_range || '').trim();
        if (time && standardTimes.has(time)) {
            if (!byTime.has(time)) byTime.set(time, period);
        } else {
            extras.push(period);
        }
    });
    const expanded = STANDARD_PERIODS.map((sp) => {
        const existing = byTime.get(sp.time);
        if (!existing) return defaultPointCardPeriod(sp);
        return {
            ...defaultPointCardPeriod(sp),
            ...existing,
            time_range: sp.time,
            location: existing.location || sp.location
        };
    });
    extras.forEach((period) => {
        const time = String(period.time_range || '').trim();
        const location = String(period.location || '').trim();
        if (time || location) expanded.push(period);
    });
    return expanded;
}

function starPointsPossible(periodOrCell) {
    return periodHasEnteredStarPoints(periodOrCell) ? 4 : 0;
}

function periodPointsPossibleValue(period) {
    if (!period) return 0;
    const raw = period.points_possible;
    if (raw === 0 || raw === '0') return 0;
    const parsed = Number(raw);
    if (Number.isFinite(parsed)) return parsed;
    return starPointsPossible(period);
}

function buildCompleteDailyPeriodsForStudent(studentId) {
    const studentData = dailyData[studentId] || {};
    const used = new Set();
    const periods = STANDARD_PERIODS.map((sp) => {
        used.add(sp.time);
        const data = studentData[sp.time] || { s: null, t: null, a: null, r: null, info: '' };
        return {
            time_range: sp.time,
            location: sp.location,
            safety_points: data.s,
            teamwork_points: data.t,
            accountability_points: data.a,
            relationships_points: data.r,
            points_possible: starPointsPossible(data),
            reset: false,
            frenzy: false,
            notes: '',
            reminders: '',
            info: data.info || '',
            infractions: []
        };
    });
    Object.keys(studentData).forEach((periodTime) => {
        if (used.has(periodTime)) return;
        const data = studentData[periodTime] || { s: null, t: null, a: null, r: null, info: '' };
        periods.push({
            time_range: periodTime,
            location: periodTime,
            safety_points: data.s,
            teamwork_points: data.t,
            accountability_points: data.a,
            relationships_points: data.r,
            points_possible: starPointsPossible(data),
            reset: false,
            frenzy: false,
            notes: '',
            reminders: '',
            info: data.info || '',
            infractions: []
        });
    });
    return periods;
}

function studentDailyDataHasInput(studentId) {
    const studentData = dailyData[studentId];
    if (!studentData) {
        return false;
    }
    return Object.keys(studentData).some(periodTime => {
        const data = studentData[periodTime];
        if (!data) return false;
        if (data.s !== null || data.t !== null || data.a !== null || data.r !== null) {
            return true;
        }
        return periodLocalHasInfo(data);
    });
}

function periodLocalHasInfo(data) {
    if (!data || data.info == null || data.info === '') {
        return false;
    }
    if (typeof data.info === 'object') {
        return typeof hasInfoData === 'function' && hasInfoData(data.info);
    }
    try {
        const parsed = JSON.parse(data.info);
        if (parsed && typeof parsed === 'object') {
            return typeof hasInfoData === 'function' && hasInfoData(parsed);
        }
    } catch (e) {
        return String(data.info).trim().length > 0;
    }
    return String(data.info).trim().length > 0;
}

function studentPeriodDataHasInput(studentId) {
    const data = periodData[studentId];
    if (!data) {
        return false;
    }
    return (data.safety_points !== null && data.safety_points !== undefined) ||
        (data.teamwork_points !== null && data.teamwork_points !== undefined) ||
        (data.accountability_points !== null && data.accountability_points !== undefined) ||
        (data.relationships_points !== null && data.relationships_points !== undefined) ||
        periodLocalHasInfo(data);
}

function markDailyFieldDirty(studentId, period, field) {
    if (studentId == null || !period || !field) return;
    const id = String(studentId);
    if (!dirtyDailyFields[id]) dirtyDailyFields[id] = {};
    if (!dirtyDailyFields[id][period]) dirtyDailyFields[id][period] = {};
    dirtyDailyFields[id][period][field] = true;
}

function markPeriodFieldDirty(studentId, field) {
    if (studentId == null || !field) return;
    const id = String(studentId);
    if (!dirtyPeriodFields[id]) dirtyPeriodFields[id] = {};
    dirtyPeriodFields[id][field] = true;
}

function markAttendanceDirty(studentId) {
    if (studentId == null) return;
    dirtyAttendanceIds[String(studentId)] = true;
}

function hasDirtyDailyEdits() {
    return Object.keys(dirtyDailyFields).length > 0 || Object.keys(dirtyAttendanceIds).length > 0;
}

function hasDirtyPeriodEdits() {
    return Object.keys(dirtyPeriodFields).length > 0;
}

function mergeDirtyMaps(target, source) {
    Object.keys(source || {}).forEach((key) => {
        const value = source[key];
        if (value && typeof value === 'object' && !Array.isArray(value)) {
            if (!target[key] || typeof target[key] !== 'object') {
                target[key] = {};
            }
            mergeDirtyMaps(target[key], value);
        } else {
            target[key] = value;
        }
    });
    return target;
}

function enqueuePeriodWrite(task) {
    const run = periodWriteChain.then(task, task);
    periodWriteChain = run.catch(function () { /* keep the write queue alive after errors */ });
    return run;
}

async function flushPendingPointCardSaves() {
    if (dailyAutosaveTimer) {
        clearTimeout(dailyAutosaveTimer);
        dailyAutosaveTimer = null;
    }
    if (periodAutosaveTimer) {
        clearTimeout(periodAutosaveTimer);
        periodAutosaveTimer = null;
    }
    const tasks = [];
    if (hasDirtyDailyEdits()) {
        tasks.push(enqueueDailyWrite(() => saveDailyAllData({ silent: true, fromAutosave: true })));
    }
    if (hasDirtyPeriodEdits()) {
        tasks.push(enqueuePeriodWrite(() => savePeriodData({ silent: true, skipReload: true })));
    }
    if (!tasks.length) {
        return true;
    }
    try {
        await Promise.all(tasks);
        return true;
    } catch (error) {
        console.error('Error flushing pending point-card saves:', error);
        return false;
    }
}

function periodRecordHasInput(period) {
    if (!period) {
        return false;
    }
    return (period.safety_points !== null && period.safety_points !== undefined) ||
        (period.teamwork_points !== null && period.teamwork_points !== undefined) ||
        (period.accountability_points !== null && period.accountability_points !== undefined) ||
        (period.relationships_points !== null && period.relationships_points !== undefined);
}

function getStudentNameById(studentId) {
    const id = parseInt(studentId, 10);
    const fromAll = allStudents.find(s => s.id === id);
    if (fromAll && fromAll.name) {
        return fromAll.name;
    }
    const fromPeriod = filteredStudentsForPeriod.find(s => s.id === id);
    return (fromPeriod && fromPeriod.name) ? fromPeriod.name : 'student';
}

function msUntilNextPointCardSubmit() {
    const now = new Date();
    const target = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 15, 0, 0);
    if (now.getTime() >= target.getTime()) {
        target.setDate(target.getDate() + 1);
    }
    return Math.max(1000, target.getTime() - now.getTime());
}

function startPointCardNightlySubmitScheduler() {
    if (pointCardNightlySubmitSchedulerStarted || !canEdit()) {
        return;
    }
    pointCardNightlySubmitSchedulerStarted = true;

    const scheduleNext = () => {
        if (pointCardNightlySubmitTimer) {
            clearTimeout(pointCardNightlySubmitTimer);
        }
        pointCardNightlySubmitTimer = setTimeout(async () => {
            await autoSubmitPointCardsIfDue();
            scheduleNext();
        }, msUntilNextPointCardSubmit());
    };
    scheduleNext();

    if (!pointCardNightlySubmitInterval) {
        pointCardNightlySubmitInterval = setInterval(() => {
            autoSubmitPointCardsIfDue();
        }, 30000);
    }

    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'hidden') {
            flushPendingPointCardSaves();
        } else if (document.visibilityState === 'visible') {
            autoSubmitPointCardsIfDue();
        }
    });
    window.addEventListener('pagehide', () => {
        flushPendingPointCardSaves();
    });
    window.addEventListener('focus', () => {
        autoSubmitPointCardsIfDue();
    });

    autoSubmitPointCardsIfDue();
}

function scheduleDailyDataLoad(delayMs) {
    if (dailyLoadDebounceTimer) {
        clearTimeout(dailyLoadDebounceTimer);
    }
    dailyLoadDebounceTimer = setTimeout(() => {
        loadDailyData();
    }, Math.max(0, delayMs || 0));
}

function invalidateDailyLoadCache(dateKey) {
    if (!dateKey) {
        dailyLoadCache.clear();
        return;
    }
    const prefix = `${dateKey}|`;
    for (const key of dailyLoadCache.keys()) {
        if (key.startsWith(prefix)) {
            dailyLoadCache.delete(key);
        }
    }
}

function handleDailyAttendanceChange(e) {
    const select = e.target;
    if (!select || !select.classList.contains('attendance-select')) {
        return;
    }
    if (!attendanceData[currentDate]) {
        attendanceData[currentDate] = {};
    }
    const studentId = parseInt(select.dataset.studentId, 10);
    const newStatus = select.value;
    if (!studentId) return;

    attendanceData[currentDate][studentId] = newStatus;
    markAttendanceDirty(studentId);

    if (newStatus === 'unexcused') {
        if (!dailyData[studentId]) {
            dailyData[studentId] = {};
        }

        STANDARD_PERIODS.forEach(period => {
            if (!dailyData[studentId][period.time]) {
                dailyData[studentId][period.time] = { s: null, t: null, a: null, r: null, info: '' };
            }
            dailyData[studentId][period.time].s = 0;
            dailyData[studentId][period.time].t = 0;
            dailyData[studentId][period.time].a = 0;
            dailyData[studentId][period.time].r = 0;
            markDailyFieldDirty(studentId, period.time, 's');
            markDailyFieldDirty(studentId, period.time, 't');
            markDailyFieldDirty(studentId, period.time, 'a');
            markDailyFieldDirty(studentId, period.time, 'r');
        });

        document.querySelectorAll(`.daily-input[data-student-id="${studentId}"]`).forEach(inputEl => {
            const category = inputEl.dataset.category;
            if (category && ['s', 't', 'a', 'r'].includes(category)) {
                inputEl.value = '0';
            }
        });
    }

    updateDailyPercentageRow();

    // Schedule an autosave of the current daily grid state
    scheduleDailyAutosave();
}

function isStarPointSelect(el) {
    return !!(el && el.tagName === 'SELECT' && el.classList && el.classList.contains('daily-input'));
}

function getStarInputsInSameGrid(currentInput) {
    const grid = currentInput && currentInput.closest
        ? currentInput.closest('#daily-grid, #students-grid')
        : null;
    const root = grid || document;
    return Array.from(root.querySelectorAll('select.daily-input'));
}

function isCoarseTouchUi() {
    try {
        return window.matchMedia('(hover: none) and (pointer: coarse)').matches;
    } catch (e) {
        return false;
    }
}

function shouldKeepStarPicker(e) {
    if (!e) return false;
    if (e.pointerType === 'touch' || e.pointerType === 'pen') return true;
    if (e.type === 'touchstart') return true;
    if (e.sourceCapabilities && e.sourceCapabilities.firesTouchEvents) return true;
    if (window.__starLastPointerWasTouch) return true;
    // Phones/tablets: keep the native dropdown for tap selection.
    if (isCoarseTouchUi()) return true;
    return false;
}

function suppressStarSelectPicker(e) {
    const select = e.target && e.target.closest ? e.target.closest('select.daily-input') : null;
    if (!isStarPointSelect(select) || select.disabled) return;
    if (e.type === 'pointerdown') {
        window.__starLastPointerWasTouch = e.pointerType === 'touch' || e.pointerType === 'pen';
    }
    if (shouldKeepStarPicker(e)) return;
    // Mouse click opens the OS picker, which swallows 0/1/2 and Backspace on the
    // first cell. Focus without opening so keyboard entry still auto-advances.
    e.preventDefault();
    if (document.activeElement !== select) {
        select.focus();
    }
}

function bindStarSelectEntryGuards() {
    if (window.__starSelectEntryGuardsBound) return;
    window.__starSelectEntryGuardsBound = true;
    document.addEventListener('pointerdown', suppressStarSelectPicker, true);
    document.addEventListener('mousedown', suppressStarSelectPicker, true);
    document.addEventListener('touchstart', (e) => {
        const select = e.target && e.target.closest ? e.target.closest('select.daily-input') : null;
        if (isStarPointSelect(select)) {
            window.__starLastPointerWasTouch = true;
            setTimeout(() => {
                window.__starLastPointerWasTouch = false;
            }, 700);
        }
    }, { capture: true, passive: true });
    document.addEventListener('pointerup', (e) => {
        if (e.pointerType === 'mouse') {
            window.__starLastPointerWasTouch = false;
        }
    }, true);
    document.addEventListener('keyup', (e) => {
        if (isStarPointSelect(e.target)) {
            handleDailyInputKeyup(e);
        }
    }, true);
}

function ensureDailyGridDelegatedListeners() {
    bindStarSelectEntryGuards();
    if (dailyGridDelegationBound) return;
    const gridContainer = document.getElementById('daily-grid-container');
    if (!gridContainer) return;

    gridContainer.addEventListener('change', (e) => {
        if (e.target && e.target.classList.contains('daily-input')) {
            handleDailyInputChange(e);
            return;
        }
        if (e.target && e.target.classList.contains('attendance-select')) {
            handleDailyAttendanceChange(e);
        }
    });

    gridContainer.addEventListener('keydown', (e) => {
        if (e.target && e.target.classList.contains('daily-input')) {
            handleDailyInputKeydown(e);
        }
    });

    gridContainer.addEventListener('click', (e) => {
        const infoBtn = e.target && e.target.closest('.info-btn');
        if (infoBtn) {
            showInfoModal({ target: infoBtn });
        }
    });

    dailyGridDelegationBound = true;
}

// Load quarter dates from localStorage or use defaults
function loadQuarterDates() {
    try {
        const stored = localStorage.getItem('quarterDates');
        if (stored) {
            return JSON.parse(stored);
        }
    } catch (e) {
        console.error('Error loading quarter dates from localStorage:', e);
    }
    // Default quarter dates (MM/DD/YYYY format)
    const currentYear = new Date().getFullYear();
    const nextYear = currentYear + 1;
    return {
        '1': { start: `08/01/${currentYear}`, end: `10/31/${currentYear}`, label: 'Quarter 1' },
        '2': { start: `11/01/${currentYear}`, end: `01/31/${nextYear}`, label: 'Quarter 2' },
        '3': { start: `02/01/${nextYear}`, end: `04/30/${nextYear}`, label: 'Quarter 3' },
        '4': { start: `05/01/${nextYear}`, end: `07/31/${nextYear}`, label: 'Quarter 4' }
    };
}

// Get current school year (August to August)
function getCurrentSchoolYear() {
    const today = new Date();
    const year = today.getFullYear();
    const month = today.getMonth() + 1; // JavaScript months are 0-indexed
    
    if (month >= 8) {  // August to December
        return `${year}-${year + 1}`;
    } else {  // January to July
        return `${year - 1}-${year}`;
    }
}

// Return admin-configured school year dates, or null if none have been saved.
function getConfiguredSchoolYearDates() {
    try {
        const stored = localStorage.getItem('schoolYearDates');
        if (stored) {
            const parsed = JSON.parse(stored);
            if (parsed && parsed.start && parsed.end) {
                return parsed;
            }
        }
    } catch (e) {
        console.error('Error loading school year dates from localStorage:', e);
    }
    return null;
}

// Load school year dates - automatically calculated (August to August)
function loadSchoolYearDates() {
    const configured = getConfiguredSchoolYearDates();
    if (configured) {
        return configured;
    }

    const currentSchoolYear = getCurrentSchoolYear();
    const [startYear, endYear] = currentSchoolYear.split('-').map(Number);
    return {
        label: currentSchoolYear,
        start: `08/01/${startYear}`,
        end: `07/31/${endYear}`
    };
}

// Format month key from "YYYY-MM" to "MonthName YY"
function formatMonthKey(monthKey) {
    try {
        const [year, month] = monthKey.split('-').map(Number);
        const monthNames = ['January', 'February', 'March', 'April', 'May', 'June',
                           'July', 'August', 'September', 'October', 'November', 'December'];
        const yearShort = String(year).slice(-2);
        return `${monthNames[month - 1]} ${yearShort}`;
    } catch (e) {
        return monthKey; // Return original if parsing fails
    }
}

function saveSchoolYearDates(schoolYearDates) {
    try {
        localStorage.setItem('schoolYearDates', JSON.stringify(schoolYearDates));
    } catch (e) {
        console.error('Error saving school year dates to localStorage:', e);
    }
}

function applySchoolCalendarConfig(config) {
    if (!config || !config.configured) {
        return false;
    }
    if (config.quarters) {
        saveQuarterDates(config.quarters);
        quarterDates = config.quarters;
    }
    if (config.school_year && config.school_year.start && config.school_year.end) {
        saveSchoolYearDates(config.school_year);
    }
    return true;
}

async function syncSchoolCalendarConfigFromServer(options = {}) {
    try {
        const response = await fetch('/api/school-calendar-config');
        if (!response.ok) {
            return false;
        }
        const data = await response.json();
        if (data.configured) {
            return applySchoolCalendarConfig(data);
        }

        // Existing installs may only have browser-local admin config; upload it once.
        if (
            options.uploadLocalIfMissing
            && typeof isAdmin === 'function'
            && isAdmin()
            && localStorage.getItem('quarterDates')
        ) {
            const localSchoolYear = getConfiguredSchoolYearDates();
            if (localSchoolYear) {
                try {
                    await saveSchoolCalendarConfigToServer(loadQuarterDates(), localSchoolYear);
                    return true;
                } catch (e) {
                    console.error('Failed to upload local school calendar config:', e);
                }
            }
        }
        return false;
    } catch (e) {
        console.error('Error loading school calendar config from server:', e);
        return false;
    }
}

async function saveSchoolCalendarConfigToServer(quarters, schoolYear) {
    const response = await fetch('/api/admin/school-calendar-config', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            quarters,
            school_year: schoolYear
        })
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
        throw new Error(data.error || 'Failed to save school calendar configuration.');
    }
    applySchoolCalendarConfig(data);
    return data;
}

function loadSchoolYearConfig() {
    // Quarter dates drive the school-year range; admin UI is refreshed via loadQuarterConfig().
}

// Helper function to convert MM/DD/YYYY to MM-DD format for backend
function extractMMDD(dateStr) {
    if (!dateStr) return '';
    // If already in MM-DD format, return as is
    if (dateStr.includes('-') && dateStr.length === 5) {
        return dateStr;
    }
    // If in MM/DD/YYYY format, extract MM-DD
    if (dateStr.includes('/')) {
        const parts = dateStr.split('/');
        if (parts.length >= 2) {
            return `${parts[0]}-${parts[1]}`;
        }
    }
    return dateStr;
}

function convertSchoolYearDatesForBackend(schoolYearDates) {
    if (!schoolYearDates) return { start: '08-01', end: '07-31' };
    
    return {
        start: extractMMDD(schoolYearDates.start),
        end: extractMMDD(schoolYearDates.end)
    };
}

// Helper function to convert quarter dates from MM/DD/YYYY to MM-DD format for backend
function convertQuarterDatesForBackend(quarterDates) {
    if (!quarterDates) {
        // Return defaults
        return {
            '1': { start: '08-01', end: '10-31', label: 'Quarter 1' },
            '2': { start: '11-01', end: '01-31', label: 'Quarter 2' },
            '3': { start: '02-01', end: '04-30', label: 'Quarter 3' },
            '4': { start: '05-01', end: '07-31', label: 'Quarter 4' }
        };
    }
    
    const converted = {};
    for (const [quarter, dates] of Object.entries(quarterDates)) {
        converted[quarter] = {
            start: extractMMDD(dates.start),
            end: extractMMDD(dates.end),
            label: dates.label || `Quarter ${quarter}`
        };
    }
    return converted;
}

function saveQuarterDates(quarterDates) {
    try {
        localStorage.setItem('quarterDates', JSON.stringify(quarterDates));
    } catch (e) {
        console.error('Error saving quarter dates to localStorage:', e);
    }
}

function parseLocalDate(date) {
    if (date instanceof Date) {
        return date;
    }
    if (typeof date === 'string') {
        const iso = date.match(/^(\d{4})-(\d{2})-(\d{2})/);
        if (iso) {
            return new Date(Number(iso[1]), Number(iso[2]) - 1, Number(iso[3]));
        }
        const mdy = date.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
        if (mdy) {
            return new Date(Number(mdy[3]), Number(mdy[1]) - 1, Number(mdy[2]));
        }
    }
    return new Date(date);
}

function toMmDd(date) {
    const dateObj = parseLocalDate(date);
    if (isNaN(dateObj.getTime())) {
        return '';
    }
    const month = dateObj.getMonth() + 1;
    const day = dateObj.getDate();
    return `${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

function isMmDdInInclusiveRange(dateStr, start, end) {
    if (!dateStr || !start || !end) {
        return false;
    }
    // Handle ranges that span across years (e.g. Nov-Jan or Aug-Jun)
    if (start <= end) {
        return dateStr >= start && dateStr <= end;
    }
    return dateStr >= start || dateStr <= end;
}

function getCurrentQuarter(date) {
    const schoolYearDates = getConfiguredSchoolYearDates();
    if (!schoolYearDates) {
        return 'School year not set';
    }

    const dateStr = toMmDd(date);
    if (!dateStr) {
        return 'Unknown Quarter';
    }

    const schoolYearStart = extractMMDD(schoolYearDates.start);
    const schoolYearEnd = extractMMDD(schoolYearDates.end);
    if (!isMmDdInInclusiveRange(dateStr, schoolYearStart, schoolYearEnd)) {
        return 'Summer';
    }

    const quarterDates = loadQuarterDates();
    for (const [, dates] of Object.entries(quarterDates)) {
        const start = extractMMDD(dates.start);
        const end = extractMMDD(dates.end);
        if (isMmDdInInclusiveRange(dateStr, start, end)) {
            return dates.label;
        }
    }

    return 'Unknown Quarter';
}

function updateQuarterDisplay() {
    const quarterValue = document.getElementById('quarter-value');
    if (quarterValue && currentDate) {
        quarterValue.textContent = getCurrentQuarter(currentDate);
    }
}

let quarterDates = loadQuarterDates();
